DELETE source_collect
FROM tb_user_article_collect source_collect
JOIN tb_user_article_collect target_collect
  ON target_collect.user_id = #{targetUserInfoId}
 AND target_collect.article_id = source_collect.article_id
WHERE source_collect.user_id = #{sourceUserInfoId}

DELETE source_history
FROM tb_user_article_history source_history
JOIN tb_user_article_history target_history
  ON target_history.user_id = #{targetUserInfoId}
 AND target_history.article_id = source_history.article_id
WHERE source_history.user_id = #{sourceUserInfoId}

DELETE source_read
FROM tb_system_notice_read source_read
JOIN tb_system_notice_read target_read
  ON target_read.user_id = #{targetUserInfoId}
 AND target_read.notice_id = source_read.notice_id
WHERE source_read.user_id = #{sourceUserInfoId}

DELETE source_role
FROM tb_user_role source_role
JOIN tb_user_role target_role
  ON target_role.user_id = #{targetUserInfoId}
 AND target_role.role_id = source_role.role_id
WHERE source_role.user_id = #{sourceUserInfoId}

